entries.syntax_block:
T = Type("Number");
T = TypeOf(Value);
IsNumber = TypeOf(Value) = Type("Number");

entries.example:
Value = 42;
Message(TypeOf(Value) = Type("Number"));   // True
Message(String(TypeOf(New Table())));       // Table

entries.syntax_block:
Desc = New TypeDescription("Number", New QualifierNumber(15, 2));
Desc = New TypeDescription("Number, String");
Desc = New TypeDescription("String", , , New QualifierString(50));

entries.example:
Money = New TypeDescription("Number", New QualifierNumber(15, 2));
Table = New Table();
Table.Columns.AddColumn("Amount", Money);
Message(Money.AdjustValue(10.555));   // 10.56

Desc = New TypeDescription("Number, String");
Message(Desc.ContainType(Type("String")));   // True
Message(Desc.ContainType(Type("Date")));     // False

Desc = New TypeDescription("Number, String");
Foreach (T In Desc.Types()) {
    Message(String(T));   // Number, then String
}

Quantity = New TypeDescription("Number", New QualifierNumber(10, 3, True));
Message(Quantity.AdjustValue(-4));       // 0
Message(Quantity.AdjustValue(1.23456));  // 1.235

Code = New TypeDescription("String", , , New QualifierString(5, AllowedLength.Fixed));
Message("[" + Code.AdjustValue("ab") + "]");        // [ab   ]
Message("[" + Code.AdjustValue("abcdefg") + "]");   // [abcde]

Key = New Guid();
Text = String(Key);            // 36 characters
Message(New Guid(Text) = Key); // True
